L4006:  .word P1S, P1E              ;USE THE FORCE, LUKE
L400A:  .word P2S, P2E              ;REMEMBER (used with PHRASE 15
L400E:  .word P3S, P3E              ;I'M ON THE LEADER
L4012:  .word P4S, P4E              ;THE FORCE IS STRONG WITH THIS ONE
L4016:  .word P5S, P5E              ;RED FIVE STANDING BY
L401A:  .word P6S, P6E              ;THIS IS RED FIVE, I'M GOING IN
L401E:  .word P7S, P7E              ;R2, TRY AND INCREASE THE POWER
L4022:  .word P8S, P8E              ;YOU'RE ALL CLEAR, KID
L4026:  .word P9S, P9E              ;LET GO, LUKE
L402A:  .word P10S, P10E            ;(BREATHING)
L402E:  .word P11S, P11E            ;YAH-HOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO
L4032:  .word P12S, P12E            ;I HAVE YOU NOW
L4036:  .word P13S, P13E            ;LOOK AT THE SIZE OF THAT THING
L403A:  .word P14S, P14E            ;STAY IN ATTACK FORMATION
L403E:  .word P15S, P15E            ;THE FORCE WILL BE WITH YOU
L4042:  .word P16S, P16E            ;ALWAYS
L4046:  .word P17S, P17E            ;R2 NO
L404A:  .word P18S, P18E            ;ELEPHANT SOUND FOR PASSBY
L404E:  .word P19S, P19E            ;I'M HIT BUT NOT BAD,R2 SEE WHAT YOU CAN DO
;WITH IT
L4052:  .word P20S, P20E            ;I'VE LOST R2
L4056:  .word P21S, P21E            ;GREAT SHOT KID, THAT WAS 2 IN A MILLION
L405A:  .word P22S, P22E            ;I CAN'T SHAKE HIM
L405E:  .word P23S, P23E            ;LUKE, TRUST ME

