;------------------------------------------------------------------------------
; AUDRY - AUDXXX-REQUEST SOUNDS
;   R2D2 YES
;------------------------------------------------------------------------------
AUDRY:
.dpage $10
L73B0:  LDY  #RY0
L73B4:  JMP  AUDNEW

;------------------------------------------------------------------------------
; AUDRD - R2D2 DONE (PHASE COMPLETED SOUND)
;------------------------------------------------------------------------------
AUDRD:
L73B7:  LDY  #RD0
L73BB:  JMP  AUDNEW

;------------------------------------------------------------------------------
; AUDXL - X WING LASER
;------------------------------------------------------------------------------
AUDXL:
L73BE:  LDY  #BL0                   ;PLAYERS SHOOTING BLAST
L73C2:  JMP  AUDNEW

;------------------------------------------------------------------------------
; AUDPB - PASS BY
;   AUDXLZ:: ;END X WING LASER
;   LDY #BLZ0 ;END PLAYER'S SHOOTING BLAST
;   JMP AUDNEW
;------------------------------------------------------------------------------
AUDPB:
L73C5:  LDY  #PB0
L73C9:  BRA  AUDNEW

;------------------------------------------------------------------------------
; AUDPBZ - END PASS BY SOUND
;------------------------------------------------------------------------------
AUDPBZ:
L73CB:  LDY  #PBZ0
L73CF:  BRA  AUDNEW

;------------------------------------------------------------------------------
; AUDSH - SHIELD
;------------------------------------------------------------------------------
