L73DD:  LDY  #TL0
L73E1:  BRA  AUDNEW

;------------------------------------------------------------------------------
; AUDTC - TIE FIGHTER CANNONS
;------------------------------------------------------------------------------
AUDTC:
L73E3:  LDY  #XL0                   ;SWITCHED FOR BETTER EFFECT
L73E7:  BRA  AUDNEW

;------------------------------------------------------------------------------
; AUDTCZ - TIE FIGHTER CANNONS
;------------------------------------------------------------------------------
AUDTCZ:
L73E9:  LDY  #XLZ0
L73ED:  BRA  AUDNEW

