;------------------------------------------------------------------------------
; AUDNEW - AUDNEW - NEW AUDIO
;   Y-->POINTER TABLE
;------------------------------------------------------------------------------
AUDNEW:
L7443:  LDA  ,Y+
L7445:  STA  AU_SHF
L7448:  LDX  #AU_BLK

AUDNEW_10:
L744B:  LSL  AU_SHF
L744E:  BCC  AUDNEW_30
L7450:  LDD  ,Y++                   ;FREQ POINTER
L7452:  STD  AUS_PNT,X
L7454:  LDD  ,Y++                   ;CONTROL/VOLUME POINTER
L7456:  STD  AUS_PNT+AUS_IZ,X
L7458:  LDA  #$01
L745A:  STA  AUS_RPT,X
L745C:  STA  AUS_TMR,X
L745E:  STA  AUS_RPT+AUS_IZ,X
L7460:  STA  AUS_TMR+AUS_IZ,X

AUDNEW_30:
L7462:  LEAX 2*AUS_IZ,X
L7464:  LDA  AU_SHF
L7467:  BNE  AUDNEW_10
L7469:  RTS

;------------------------------------------------------------------------------
; AUDDO - AUDDO - UPDATE AUDIO EVERY 16 MILS
;   AUDIO DO - EVERY 16 MILS
;------------------------------------------------------------------------------
AUDDO:
L746A:  LDX  #AU_BLK                ;AUDIO CHANNEL INFO
L746D:  LDB  #$00                   ;POKEY CHANNEL OFFSET

AUDDO_10:
L746F:  LDY  AUS_PNT,X              ;Y-->AUDIO PHRASE TABLE
L7472:  BEQ  AUDDO_55               ;? POINTER VALID?
L7474:  DEC  AUS_TMR,X              ;THEN PROCEED WITH CHANNEL
L7476:  BNE  AUDDO_55               ;? DONE WITH CURRENT NOTE?
L7478:  DEC  AUS_RPT,X
L747A:  BNE  AUDDO_40               ;? DONE WITH CURRENT PHRASE?
L747C:  LEAY TAS_IZ,Y               ;THEN BUMP TO NEXT PHRASE
L747E:  STY  AUS_PNT,X
L7481:  LDA  TAS_RPT-TAS_IZ,Y
L7483:  BNE  AUDDO_35               ;?END OF ALL PHRASES?
L7485:  STA  AUS_PNT,X              ;THEN TURN OFF AUDIO POINTER
L7487:  STA  AUS_PNT+1,X
L7489:  BRA  AUDDO_45               ;J TURN OFF CHANNEL

AUDDO_35:        ;---ANOTHER PHRASE EXISTS
L748B:  STA  AUS_RPT,X              ;REPEAT COUNT
L748D:  LDA  TAS_SND-TAS_IZ,Y       ;NEW CURRENT SOUND
L748F:  STA  AUS_SND,X
L7491:  BRA  AUDDO_42               ;J BEGIN NEW SOUND

AUDDO_40:        ;---ELSE CONTINUE WITH PHRASE
L7493:  LDA  AUS_SND,X              ;INCREMENT SOUND CHANNEL VALUE
L7495:  ADDA TAS_INC-TAS_IZ,Y
L7497:  STA  AUS_SND,X

AUDDO_42:
L7499:  LDA  TAS_TMR-TAS_IZ,Y       ;RESET TIMER FOR PHRASE
L749B:  STA  AUS_TMR,X
L749D:  LDA  AUS_SND,X

AUDDO_45:
;A:=NEW CHANNEL VALUE
L749F:  LDY  #P_BASE                ;Y-->POKEY CHANNELS
L74A3:  STA  B,Y                    ;OFFSET IN BREG

AUDDO_55:        ;---END IFEQ
AUDDO_60:        ;---END IFNE
L74A5:  LEAX AUS_IZ,X
L74A7:  INCB
L74A8:  CMPB #AUS_EQ
L74AA:  BLO  AUDDO_10
L74AC:  RTS

