L74C9:  .word $734F                 ;OFFSET SS  SHOOT SHOTS
L74CB:  .word $7354                 ;OFFSET BL  PLAYER'S LASER BLAST
;OFFSET BLZ ;END PLAYER'S LASER BLAST
L74CD:  .word $735D                 ;OFFSET PH  PORT HOLE SHOT
L74CF:  .word $736E                 ;OFFSET RS  R2 SHAVE
L74D1:  .word $7373                 ;OFFSET TH  THRUSTING DOWN TO DEATH STAR
L74D3:  .word $737C                 ;OFFSET PBZ  END PASSBY SOUND
L74D5:  .word $7385                 ;OFFSET YEA  YAY, TEST SUCCESSFUL
L74D7:  .word $738A                 ;OFFSET NAY  NAY, TEST BIT BIG ONE
L74D9:  .word $738F                 ;OFFSET TST  TEST TONES FOR YOUR LISTENING PLEASURE

;==============================================================================
; MODULE SNDPM   SNDPM.MAC
;   REMOTE SOUND BOARD VERSION
;==============================================================================

;.SBTTL VOICE PARAMETERS

TVC:
TVC1:
;POKEY (VOICE 1)
L74DB:  .word VOICE1                ;.TVC 1,PKFL1,16 PKFL1 0
L74DD:  .byte VC1
L74DE:  .word PKFL1
L74E0:  .byte $00
L74E1:  .word PKFL1

TVC2:
;POKEY (VOICE 2)
L74E3:  .word VOICE2                ;.TVC 2,PKFL2,16 PKFL2 0
L74E5:  .byte VC2
L74E6:  .word PKFL2
L74E8:  .byte $00
L74E9:  .word PKFL2

TVC3:
;POKEY (VOICE 3 OR 3A)
L74EB:  .word VOICE3                ;.TVC 3,PKFL3,16 PKFL3 0
L74ED:  .byte VC3
L74EE:  .word PKFL3
L74F0:  .byte $00
L74F1:  .word PKFL3

TVC4:
;*** NON-SPLIT 16 BIT VOICE 4
L74F3:  .word VOICE4                ;.TVC 4,PKFL4,16 PKFL4 0
L74F5:  .byte VC4
L74F6:  .word PKFL4
L74F8:  .byte $00
L74F9:  .word PKFL4

TVC5:
L74FB:  .word VOICE5                ;.TVC 5,PKFL4,16 PKFH4 VC4
L74FD:  .byte VC5
L74FE:  .word PKFL4
L7500:  .byte VC4
L7501:  .word PKFH4

TVC6:
L7503:  .word VOICE6                ;.TVC 6,PKFL4,16 PKFH1 VC4!VC5
L7505:  .byte VC6
L7506:  .word PKFL4
L7508:  .byte VC4|VC5
L7509:  .word PKFH1

TVC7:
L750B:  .word VOICE7                ;.TVC 7,PKFL4,16 PKFH2 VC4!VC5!VC6
L750D:  .byte VC7
L750E:  .word PKFL4
L7510:  .byte VC4|VC5|VC6
L7511:  .word PKFH2

TVC8:
L7513:  .word VOICE8                ;.TVC 8,PKFL4,16 PKFH3 VC4!VC5!VC6!VC7
L7515:  .byte VC8
L7516:  .word PKFL4
L7518:  .byte VC4|VC5|VC6|VC7
L7519:  .word PKFH3

;------------------------------------------------------------------------------
; PMSF2 - MACRO DEFINITIONS
;   SPECIAL EFFECT(PROTON TORPEDO)
;   END OF VOICE RAM BLOCKS
;   (also: TVCZ)
;------------------------------------------------------------------------------
PMSF2:
TVCZ:
L751B:  JSR  PKCUT1                 ;.TUNE 1,1
L751E:  LDB  #$02
L7520:  JSR  NWTUNE
L7523:  JSR  PKCUT2                 ;.TUNE 2,2
L7526:  LDB  #$04
L7528:  JSR  NWTUNE
L752B:  JSR  PKCUT3                 ;.TUNE 3,3
L752E:  LDB  #$06
L7530:  JSR  NWTUNE
L7533:  JSR  PKCUT4                 ;.TUNE 4,4
L7536:  LDB  #$08
L7538:  JSR  NWTUNE
L753B:  RTS

;------------------------------------------------------------------------------
; PMBEN - BENS THEME (START OF TOWER)
;------------------------------------------------------------------------------
PMBEN:
L753C:  JSR  PKCUT1                 ;.TUNE 1,7
L753F:  LDB  #$0E
L7541:  JSR  NWTUNE
L7544:  JSR  PKCUT2                 ;.TUNE 2,8
L7547:  LDB  #$10
L7549:  JSR  NWTUNE
L754C:  JSR  PKCUT3                 ;.TUNE 3,9
L754F:  LDB  #$12
L7551:  JSR  NWTUNE
L7554:  JSR  PKCUT4                 ;.TUNE 4,10
L7557:  LDB  #$14
L7559:  JSR  NWTUNE
L755C:  RTS

;------------------------------------------------------------------------------
; PMCNT - CANTENA (HI SCORE)
;------------------------------------------------------------------------------
PMCNT:
L755D:  JSR  PKCUT1                 ;.TUNE 1,11
L7560:  LDB  #$16
L7562:  JSR  NWTUNE
L7565:  JSR  PKCUT2                 ;.TUNE 2,12
L7568:  LDB  #$18
L756A:  JSR  NWTUNE
L756D:  JSR  PKCUT3                 ;.TUNE 3,13
L7570:  LDB  #$1A
L7572:  JSR  NWTUNE
L7575:  JSR  PKCUT4                 ;.TUNE 4,14
L7578:  LDB  #$1C
L757A:  JSR  NWTUNE
L757D:  RTS

;------------------------------------------------------------------------------
; PMEND - (AFTER DETH STAR EXPLOSION)
;------------------------------------------------------------------------------
PMEND:
L757E:  JSR  PKCUT1                 ;.TUNE 1,15
L7581:  LDB  #$1E
L7583:  JSR  NWTUNE
L7586:  JSR  PKCUT2                 ;.TUNE 2,16
L7589:  LDB  #$20
L758B:  JSR  NWTUNE
L758E:  JSR  PKCUT3                 ;.TUNE 3,17
L7591:  LDB  #$22
L7593:  JSR  NWTUNE
L7596:  JSR  PKCUT4                 ;.TUNE 4,18
L7599:  LDB  #$24
L759B:  JSR  NWTUNE
L759E:  RTS

;------------------------------------------------------------------------------
; PMREB - REBEL THEME (TRANSITION INTO TRENCH)
;------------------------------------------------------------------------------
PMREB:
L759F:  JSR  PKCUT1                 ;.TUNE 1,19
L75A2:  LDB  #$26
L75A4:  JSR  NWTUNE
L75A7:  JSR  PKCUT2                 ;.TUNE 2,20
L75AA:  LDB  #$28
L75AC:  JSR  NWTUNE
L75AF:  JSR  PKCUT3                 ;.TUNE 3,21
L75B2:  LDB  #$2A
L75B4:  JSR  NWTUNE
L75B7:  JSR  PKCUT4                 ;.TUNE 4,22
L75BA:  LDB  #$2C
L75BC:  JSR  NWTUNE
L75BF:  RTS

;------------------------------------------------------------------------------
; PMRRP - REBEL THEME WITH REPEATS(TRENCH WITH REPEATS)
;------------------------------------------------------------------------------
PMRRP:
L75C0:  JSR  PKCUT1                 ;.TUNE 1,23
L75C3:  LDB  #$2E
L75C5:  JSR  NWTUNE
L75C8:  JSR  PKCUT2                 ;.TUNE 2,24
L75CB:  LDB  #$30
L75CD:  JSR  NWTUNE
L75D0:  JSR  PKCUT3                 ;.TUNE 3,25
L75D3:  LDB  #$32
L75D5:  JSR  NWTUNE
L75D8:  JSR  PKCUT4                 ;.TUNE 4,26
L75DB:  LDB  #$34
L75DD:  JSR  NWTUNE
L75E0:  RTS

;------------------------------------------------------------------------------
; PMTH5 - MAIN THEME (START OF GAME)
;------------------------------------------------------------------------------
PMTH5:
L75E1:  JSR  PKCUT1                 ;.TUNE 1,27
L75E4:  LDB  #$36
L75E6:  JSR  NWTUNE
L75E9:  JSR  PKCUT2                 ;.TUNE 2,28
L75EC:  LDB  #$38
L75EE:  JSR  NWTUNE
L75F1:  JSR  PKCUT3                 ;.TUNE 3,29
L75F4:  LDB  #$3A
L75F6:  JSR  NWTUNE
L75F9:  JSR  PKCUT4                 ;.TUNE 4,30
L75FC:  LDB  #$3C
L75FE:  JSR  NWTUNE
L7601:  RTS

;------------------------------------------------------------------------------
; PM4TH - BATTLE MUSIC IN FOURTHS
;------------------------------------------------------------------------------
PM4TH:
L7602:  JSR  PKCUT1                 ;.TUNE 1,31
L7605:  LDB  #$3E
L7607:  JSR  NWTUNE
L760A:  JSR  PKCUT2                 ;.TUNE 2,32
L760D:  LDB  #$40
L760F:  JSR  NWTUNE
L7612:  JSR  PKCUT3                 ;.TUNE 3,33
L7615:  LDB  #$42
L7617:  JSR  NWTUNE
L761A:  JSR  PKCUT4                 ;.TUNE 4,34
L761D:  LDB  #$44
L761F:  JSR  NWTUNE
L7622:  RTS

;------------------------------------------------------------------------------
; PMTHB - THEME TYPE B
;------------------------------------------------------------------------------
PMTHB:
L7623:  JSR  PKCUT1                 ;.TUNE 1,35
L7626:  LDB  #$46
L7628:  JSR  NWTUNE
L762B:  JSR  PKCUT2                 ;.TUNE 2,36
L762E:  LDB  #$48
L7630:  JSR  NWTUNE
L7633:  JSR  PKCUT3                 ;.TUNE 3,37
L7636:  LDB  #$4A
L7638:  JSR  NWTUNE
L763B:  JSR  PKCUT4                 ;.TUNE 4,38
L763E:  LDB  #$4C
L7640:  JSR  NWTUNE
L7643:  RTS

;------------------------------------------------------------------------------
; PMDES - DESCENT TO DETH STAR
;------------------------------------------------------------------------------
PMDES:
L7644:  JSR  PKCUT1                 ;.TUNE 1,39
L7647:  LDB  #$4E
L7649:  JSR  NWTUNE
L764C:  JSR  PKCUT2                 ;.TUNE 2,40
L764F:  LDB  #$50
L7651:  JSR  NWTUNE
L7654:  JSR  PKCUT3                 ;.TUNE 3,41
L7657:  LDB  #$52
L7659:  JSR  NWTUNE
L765C:  JSR  PKCUT4                 ;.TUNE 4,42
L765F:  LDB  #$54
L7661:  JSR  NWTUNE
L7664:  RTS

;------------------------------------------------------------------------------
; PMDAR - LORD VADER'S THEME
;------------------------------------------------------------------------------
PMDAR:
L7665:  JSR  PKCUT1                 ;.TUNE 1,43
L7668:  LDB  #$56
L766A:  JSR  NWTUNE
L766D:  JSR  PKCUT2                 ;.TUNE 2,44
L7670:  LDB  #$58
L7672:  JSR  NWTUNE
L7675:  JSR  PKCUT3                 ;.TUNE 3,45
L7678:  LDB  #$5A
L767A:  JSR  NWTUNE
L767D:  JSR  PKCUT4                 ;.TUNE 4,46
L7680:  LDB  #$5C
L7682:  JSR  NWTUNE
L7685:  RTS

;------------------------------------------------------------------------------
; PMTST - MUSIC CHANNEL TEST TONES
;------------------------------------------------------------------------------
PMTST:
L7686:  JSR  PKCUT3                 ;.TUNE 3,47  CHANNEL #S CHANGED TO BE IN ORDER OF
L7689:  LDB  #$5E
L768B:  JSR  NWTUNE
;POKEYS ON BOARD (WAS 1,2,3,4, NOW 3,4,1,2)
L768E:  JSR  PKCUT4                 ;.TUNE 4,48
L7691:  LDB  #$60
L7693:  JSR  NWTUNE
L7696:  JSR  PKCUT1                 ;.TUNE 1,49
L7699:  LDB  #$62
L769B:  JSR  NWTUNE
L769E:  JSR  PKCUT2                 ;.TUNE 2,50
L76A1:  LDB  #$64
L76A3:  JSR  NWTUNE
L76A6:  RTS

;------------------------------------------------------------------------------
; ISND - RPM POKEY INITIALIZATION
;   ISND
;   SUB. TO INITIALIZE POKEY FOR USE
;------------------------------------------------------------------------------
ISND:
L76A7:  LDA  #$00                   ;SET UP FOR POKEY VOICE 1
L76A9:  STA  PKI1                   ;ALSO, INIT POKEY DEVICES
L76AC:  STA  PKI2
L76AF:  STA  DREF                   ;CLEAR DYN. RECON. FLAG
L76B1:  JSR  PKCUT1                 ;.IRPC VNUM,<12345678>
L76B4:  JSR  PKCUT2
L76B7:  JSR  PKCUT3
L76BA:  JSR  PKCUT4
L76BD:  JSR  PKCUT5
L76C0:  JSR  PKCUT6
L76C3:  JSR  PKCUT7
L76C6:  JSR  PKCUT8
L76C9:  LDA  #$03
L76CB:  STA  PKI1                   ;OUTPUT SECOND BYTE TO POKEY INIT.
L76CE:  STA  PKI2
L76D1:  LDA  #$78                   ;VOICES 3 AND 4 ARE 16 BIT EACH
L76D3:  STA  PKC1
L76D6:  LDA  #$78
L76D8:  STA  PKC2                   ;TIE CHANNEL 2 TO 1, 4 TO 3
L76DB:  RTS

;------------------------------------------------------------------------------
; RCS - RCS,RCN
;   SET OR RESET DYNAMIC RECONFIGURATION FLAG AND INIT ALL VOICES
;------------------------------------------------------------------------------
RCS:
L76DC:  LDA  #$00                   ;ALL CHANNELS SEPERATE
L76DE:  STA  PKC1
L76E1:  STA  PKC2
L76E4:  LDA  #$01                   ;SET FLAG THAT ARE ALL 8-BIT VOICES NOW
L76E6:  BNE  RECON

RCN:
L76E8:  LDA  #$78                   ;VOICES 3 AND 4 ARE 16 BIT EACH
L76EA:  STA  PKC1
L76ED:  LDA  #$78
L76EF:  STA  PKC2                   ;TIE CHANNEL 2 TO 1, 4 TO 3
L76F2:  CLRA                        ;CLEAR FLAG (NORMAL CONFIGURATION)

RECON:
L76F3:  STA  DREF                   ;INDICATE CURRENT CONFIGURATION
L76F5:  BSR  PKCUT1                 ;.IRPC VNUM,<12345678>
L76F7:  BSR  PKCUT2
L76F9:  BSR  PKCUT3
L76FB:  BSR  PKCUT4
L76FD:  BSR  PKCUT5
L76FF:  BSR  PKCUT6
L7701:  BSR  PKCUT7
L7703:  BSR  PKCUT8
L7705:  RTS

;------------------------------------------------------------------------------
; PKCUT1 - [note] Cut (init) POKEY voice 1: A = VCS_1, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT1:
L7706:  LDA  #VCS_1                 ;.IRPC VNUM,<12345678>
L7708:  BRA  POKVI

;------------------------------------------------------------------------------
; PKCUT2 - [note] Cut (init) POKEY voice 2: A = VCS_2, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT2:
L770A:  LDA  #VCS_2
L770C:  BRA  POKVI

;------------------------------------------------------------------------------
; PKCUT3 - [note] Cut (init) POKEY voice 3: A = VCS_3, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT3:
L770E:  LDA  #VCS_3
L7710:  BRA  POKVI

;------------------------------------------------------------------------------
; PKCUT4 - [note] Cut (init) POKEY voice 4: A = VCS_4, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT4:
L7712:  LDA  #VCS_4
L7714:  BRA  POKVI

;------------------------------------------------------------------------------
; PKCUT5 - [note] Cut (init) POKEY voice 5: A = VCS_5, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT5:
L7716:  LDA  #VCS_5
L7718:  BRA  POKVI

;------------------------------------------------------------------------------
; PKCUT6 - [note] Cut (init) POKEY voice 6: A = VCS_6, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT6:
L771A:  LDA  #VCS_6
L771C:  BRA  POKVI

;------------------------------------------------------------------------------
; PKCUT7 - [note] Cut (init) POKEY voice 7: A = VCS_7, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT7:
L771E:  LDA  #VCS_7
L7720:  BRA  POKVI

;------------------------------------------------------------------------------
; PKCUT8 - [note] Cut (init) POKEY voice 8: A = VCS_8, branch to POKVI; leaves Y-->voice descriptor table
;------------------------------------------------------------------------------
PKCUT8:
L7722:  LDA  #VCS_8
L7724:  BRA  POKVI

;------------------------------------------------------------------------------
; POKVI - POKVI,Y
;   SUB. TO INIT A POKEY VOICE
;   POKVI:
;   A:=OFFSET INTO VOICE DESCRIPTOR TABLE
;   POKVIY:
;   Y:=POINTER TO THIS VOICE'S DESCRIPTOR TABLE
;------------------------------------------------------------------------------
POKVI:
L7726:  LDX  #TVC                   ;BASE OF VOICE
L7729:  LEAY A,X                    ;Y-->VOICE DESCRIPTOR TABLE

POKVIY:          ;Y SETUP BY NOW
L772B:  LDU  VCS_RAM,Y              ;U-->VOICE RAM BLOCK
;;; ;NOW IS MAINLINE ROUTINE
;;; ;AVOIDING IRQ INTERACTIONS
L772D:  LDA  VCS_BIT,Y              ;BIT FOR THIS VOICE
L772F:  COMA                        ;PREPARE TURNOFF MASK
L7730:  ANDA VIU
L7732:  STA  VIU                    ;TURN OFF VIU BIT
L7734:  LDA  #$07
L7736:  STA  VVOL,U                 ;SET UP TO MEDIAN VOLUME
L7738:  LDA  #$C0                   ;REMEMBER TO PRE-NEGATE
L773A:  STA  ORATE,U                ;SET UP TO MED. RATE
L773C:  LDA  #$A0                   ;DEFAULT TO PURE TONES
L773E:  STA  VAC,U                  ;STORE AS VOICE CONTROL BITS
L7740:  LDD  #$0000                 ;CLEARING OUT VARIABLES
L7743:  STD  OPTR,U                 ;CLEAR VOICE IN USE FLAG(HI BYTE POINTER)
L7745:  STA  OKEY,U                 ;SET BACK TO UNUSED KEY
L7747:  STA  VSEQ,U                 ;CLEAR ENV. SEQ. COUNT
L7749:  STD  ODUR,U
L774B:  STA  VLC,U                  ;CLEAR LOOP COUNT
L774E:  STD  OPTSV,U                ;CLEAR SUB-PHRASE POINTER (FLAG)
L7751:  STA  VSF,U                  ;CLEAR SYNTH. MODE
L7753:  STD  VSA,U                  ;CLEAR SYNTH. MODE ADJUSTMENT
L7756:  LDD  FETAB
L7759:  STD  APTR,U
L775B:  STD  FPTR,U
;TURN OFF POKEY AMPLITUDE
L775D:  LDX  VCS_PKF,Y              ;SELECT THE POKEY OUTPUT PORT
L775F:  LDB  DREF
L7761:  BEQ  POKVIY_62              ;?DYNAMICALLY RECONFIG'D?
L7763:  LDX  VCS_PKD,Y              ;THEN USE DRE PORT INSTEAD
L7765:  CLR  1,X                    ;ONLY DO LO 8 BITS
L7767:  RTS

POKVIY_62:
POKVIY_67:
L7768:  CLR  3,X                    ;AMPLITUDE GOES IN SECOND CHANNEL FOR 16 BIT
L776A:  RTS

;------------------------------------------------------------------------------
; NWTUNE - NWTUNE
;   SETS UP NEW TUNE INTO GIVEN VOICE
;   MUST BE PRECEEDED BY PKCUT TO CLEAR OUT
;   ANY OLD VOICE AND SETUP Y-->DESCRIPTOR TABLE
;   B:= TUNE # WORD OFFSET INTO TUNE TABLE
;------------------------------------------------------------------------------
NWTUNE:
L776B:  LDX  #TUNTAB                ;BASE OF TUNE DIRECTORY
L776E:  ABX                         ;ALLOW 128 WORD ENTRIES
L776F:  LDD  ,X                     ;POINTER TO TUNE
L7771:  LDX  VCS_RAM,Y              ;X-->VOICE RAM BLOCK
L7773:  STD  OPTR,X
L7775:  LDA  VIU                    ;SET VOICE IN USE BIT
L7777:  ORA  VCS_BIT,Y              ;THATS OUR BIT
L7779:  STA  VIU
L777B:  RTS

;------------------------------------------------------------------------------
; PKDR - INTERRUPT ROUTINES, PKDR, POKOUT
;   PKDR
;   POKEY 4MS INTERRUPT DRIVER
;------------------------------------------------------------------------------
PKDR:
L777C:  LDA  S_INTCT                ;WHICH POKEY TO UPDATE THIS FRAME
L777E:  LSRA
L777F:  BCC  PKDR_10                ;IF VOICE 2 THIS FRAME
L7781:  LDA  #VCS_1
L7783:  BSR  POKOUT                 ;OUTPUT TO POKEY (VOICE 1)
L7785:  LDA  #VCS_3
L7787:  BSR  POKOUT                 ;OUTPUT TO POKEY (VOICE 3)
L7789:  LDA  #VCS_5                 ;OUTPUT VOICE 5 IF IT EXISTS
L778B:  BSR  POKOUT
L778D:  LDA  #VCS_7                 ;OUTPUT VOICE 7 IF IT EXISTS
L778F:  BSR  POKOUT
L7791:  RTS

PKDR_10:         ;IF HERE, TIME TO OUTPUT VOICE 2
L7792:  LDA  #VCS_2
L7794:  BSR  POKOUT                 ;OUTPUT TO POKEY (VOICE 2)
L7796:  LDA  #VCS_4
L7798:  BSR  POKOUT                 ;OUTPUT TO POKEY (VOICE 4 OR 4A)
L779A:  LDA  #VCS_6                 ;OUTPUT VOICE 6 IF DEFINED
L779C:  BSR  POKOUT
L779E:  LDA  #VCS_8                 ;OUTPUT VOICE 8 IF IT EXISTS
L77A0:  BSR  POKOUT
L77A2:  RTS

;------------------------------------------------------------------------------
; POKOUT - POKOUT
;   COMMON OUTPUT ROUTINE FOR ALL POKEY VOICES
;   A:= OFFSET INTO CURRENT VOICE DESCRIPTOR TABLE
;------------------------------------------------------------------------------
POKOUT:
L77A3:  LDX  #TVC                   ;BASE OF VOICE DESCRIPTOR TABLE
L77A6:  LEAY A,X                    ;Y--> THIS VOICE'S DESCRIPTOR TABLE
L77A8:  LDU  VCS_RAM,Y              ;U--> RAM BLOCK FOR THIS VOICE
L77AA:  LDA  OPTR,U                 ;?VOICE IN USE? (INUSE IF HI POINTER SET)
L77AC:  BNE  POKOUT_3               ;B THEN PROCESS IT
L77AE:  RTS                         ;ELSE, RETURN

POKOUT_3:
;SEE IF TIME TO UPDATE CURRENT NOTE
L77AF:  INC  VSEQ,U                 ;INC. ENVELOPE SEQ. COUNT
L77B1:  BNE  POKOUT_5               ;IF NOT AT END OF ENV. YET
L77B3:  DEC  VSEQ,U                 ;ELSE, KEEP AT FINAL ENV. COUNT

POKOUT_5:
L77B5:  LDB  ORATE,U                ;PRE-NEGATED RATE (8 BITS, SIGN IMPLIED)
L77B7:  LDA  #$FF                   ;EXTEND IMPLIED SIGN
L77B9:  ADDD ODUR,U                 ;BY ADDING NEGATIVE OF CURRENT RATE,
L77BB:  STD  ODUR,U                 ;UPDATE CURRENT NOTE DURATION
L77BD:  LBPL POKSN                  ;B IF STILL SAME NOTE

;------------------------------------------------------------------------------
; POKNL - IF HERE, HAVE A NEW NOTE TO PLAY
;------------------------------------------------------------------------------
POKNL:
L77C1:  LDX  OPTR,U                 ;GET THIS NOTE IN TUNE
L77C3:  LDB  ,X++                   ;BUMP TO NEXT INSTRUCTION
L77C5:  STX  OPTR,U
L77C7:  TSTB                        ;CHECK THE OPCODE(FIRST BYTE)
L77C8:  LBMI PKFUN                  ;B IF A FUNCTION
L77CC:  BEQ  POKNL_9                ;?SOUNDFUL NOTE?(NOT A REST)
L77CE:  ADDB OKEY,U                 ;THEN POSITION NOTE TO CURRENT KEY

POKNL_9:
L77D0:  LDA  DREF                   ;ELSE NO SPLIT VOICE, BUT HAVE DYN RECONF
L77D2:  BEQ  POKNL_68               ;B IF FULL 16 BIT PORT
L77D4:  CLRA                        ;ELSE USE 8 BIT VALUE DIRECTLY
L77D5:  BRA  POKNL_69

POKNL_68:        ;---ELSE IS 16 BIT -- CALC MUSIC NOTE
L77D7:  LSLB                        ;WORD OFFSET
L77D8:  LDX  #NOTTAB                ;BASE OF NOTE CONVERSION TABLE
L77DB:  ABX                         ;UNSIGNED, FULL RANGE
L77DC:  LDD  ONOTE,U                ;COMPUTE DELTA BETWEEN NEW AND OLD
L77DE:  SUBD ,X                     ;SUB NEW NOTE VALUE
L77E0:  STD  VSA,U                  ;SAVE DELTA FOR SYNTH MODE
L77E3:  LDD  ,X                     ;GET NOTE VALUE

POKNL_69:
L77E5:  STD  ONOTE,U                ;STORE AS OUTPUT NOTE
L77E7:  LDX  OPTR,U                 ;GET DURATION OF CURRENT NOTE
L77E9:  LDA  -$1,X                  ;(WE PREVIOUSLY BUMPED POINTER TO NEXT NOTE)
L77EB:  BNE  POKNL_30               ;?AT FINAL NOTE?
L77ED:  LDD  OPTSV,U                ;CHECK FOR ENDING SUB-PHRASE OR MAIN TUNE
L77F0:  LBEQ POKVIY                 ;B END OF MAIN TUNE, INIT THIS VOICE
L77F4:  STD  OPTR,U                 ;IF HERE, RETURNING FROM SUB-PHRASE
L77F6:  LDD  #$0000
L77F9:  STD  OPTSV,U                ;RESET SUB-PHRASE FLAG
L77FC:  JMP  POKNL                  ;J GET A NOTE GOING

POKNL_30:        ;---STILL HAVE A NEW NOTE, GET AND STORE DURATION
;A:=DURATION (SECOND BYTE)
;X-->FOLLOWING INSTR
L77FF:  CLRB                        ;PREPARE LSB
L7800:  LSRA                        ;SHIFT AND REMOVE LSB (TIED NOTE FLAG)
L7801:  LSRA                        ;MULT. DUR * 128 (CARRY IS MSB OF LSB BYTE)
L7802:  RORB                        ;ROTATE INTO LSB'S
L7803:  ADDD ODUR,U                 ;SUBTRACT ANY OVERRUN FROM PREV. NOTE
;SUBD #0FFFF ;(?6502 VERSION)ADD 1 TO COMPENSATE FOR SUBTRACT TEST
L7805:  STD  ODUR,U
L7807:  LDA  -$1,X                  ;GET BACK DURATION
L7809:  ANDA #$01                   ;TEST IF NOTE IS TIED
L780B:  BNE  POKNL_50               ;?NOTE NOT TIED?
L780D:  STA  VSEQ,U                 ;CLEAR SEQ. COUNTER FOR NOT TIED NOTE
L780F:  CLRB                        ;AND NO SYNTH ADJUST FOR NOT TIED
L7810:  STD  VSA,U
L7813:  LDA  VIU                    ;TEST IF THIS IS NOT HIGH PRIORITY
L7815:  ANDA VCS_PRI,Y              ;IN USE BITS VS PRIORITY MASK
;BEQ PKNOFF ;IF THIS IS HIGH PRIORITY FOR THIS VOICE
L7817:  BEQ  POKSN                  ;LET AMPLITUDE ENVELOPE DO PRE-GAP
L7819:  LDA  DREF
;BNE PKNOFF
L781B:  BNE  POKSN                  ;LET AMPLITUDE ENVELOPE DO PRE-GAP
L781D:  RTS                         ;ELSE, DON'T UPDATE POKEY WITH THIS VOICE

POKNL_50:
L781E:  LDA  VSF,U                  ;TEST SYNTH MODE FLAG
L7820:  BNE  POKSN                  ;B IF SYNTH MODE ON
;NOTE IS TIED AND SYNTH MODE NOT ON, CLEAR FREQ. ADJUSTMENT
L7822:  CLRB
L7823:  STD  VSA,U                  ;CLEAR SYNTH. ADJUST

POKSN:           ;HAVE SAME NOTE AS LAST TIME, PLAY IT WITH ENVELOPES
L7826:  LDA  VIU
L7828:  ANDA VCS_PRI,Y              ;IN USE FLAGS VS PRIORITY MASK
L782A:  BEQ  POKSN_61               ;IF AT HIGHEST PRIORITY, PLAY NOTE
L782C:  LDA  DREF
L782E:  BNE  POKSN_61               ;ELSE IF RECONFIGURED, THEN ALL ARE AT BEST PRIORITY
L7830:  RTS                         ;ELSE, RETURN WITHOUT POKEY UPDATE

POKSN_61:
L7831:  LDA  S_INTCT
L7833:  ANDA #$06                   ;?TIME TO CHANGE ADJUST?
L7835:  BNE  POKSN_3
L7837:  ASR  VSA,U                  ;DIVIDE SYNTH ADJUST BY 2
L783A:  ROR  VSA+1,U                ;SO ADD 1/2 AS MUCH EACH TIME

POKSN_3:         ;---FIRST ADD FREQ. ENV. TO NOTE FREQ.
L783D:  LDB  VSEQ,U                 ;GET FREQ. ENV. SEQ. #
L783F:  LSRB                        ;FOR 128 BYTE TABLE
L7840:  LDX  FPTR,U                 ;BASE OF FREQUENCY TABLE
L7842:  ABX
L7843:  LDB  ,X                     ;GET CURRENT FREQ. ENV. SETTING
L7845:  SEX                         ;CONVERT TO 16 BIT
L7846:  TST  DREF                   ;MUSIC FREQ IS *8, SOUNDS ARE AS IS.
L7848:  BNE  POKSN_78               ;B IF RECONFIG'D TO 8 BITS
L784A:  LSLB                        ;MULT FREQ ENV *8 FOR MUSIC
L784B:  ROLA
L784C:  LSLB
L784D:  ROLA
L784E:  LSLB
L784F:  ROLA

POKSN_78:
L7850:  ADDD ONOTE,U                ;ADD IN THE NOTES FREQUENCY
L7852:  ADDD VSA,U                  ;ADD SYNTH ADJUST TO SUM OF NOTE FREQ. AND ENV.
L7855:  LDX  VCS_PKF,Y              ;SELECT THE POKEY OUTPUT PORT
L7857:  TST  DREF
L7859:  BEQ  POKSN_62               ;?DYNAMICALLY RECONFIG'D?
L785B:  LDX  VCS_PKD,Y              ;THEN USE DRE PORT INSTEAD
L785D:  BRA  POKSN_63               ;AND ONLY DO LO 8 BITS

POKSN_62:
L785F:  STA  2,X                    ;OUTPUT MSB OF 16 BIT

POKSN_63:
L7861:  STB  ,X                     ;OUTPUT LO 8 BIT
L7863:  LDD  ONOTE,U                ;CHECK FOR A REST(NO OUTPUT)
L7865:  BNE  PKNON                  ;IF NOT A REST

PKNOFF:          ;HAVE A REST OR NOTE IS OFF, SET UP TO FORCE OUTPUT TO OFF
L7867:  LDA  #$F0
L7869:  STA  FASV                   ;STORE MASK TO ZERO OUT AMPLITUDE
L786B:  BRA  PKNC

;------------------------------------------------------------------------------
; PKNON - NOW OUTPUT AMPLITUDE, THIS VOICE
;------------------------------------------------------------------------------
PKNON:
L786D:  LDA  #$FF                   ;SET UP MASK TO PERMIT CURRENT VOLUME
L786F:  STA  FASV

PKNC:
L7871:  LDB  VSEQ,U                 ;;DIVIDE ENV. SEQ # BY 8 (32 BYTE ENV. TABLE)
;USE STRAIGHT, LIMIT AT 31(QUARTER SECOND)
L7873:  CMPB #$1F
L7875:  BLO  L7879                  ;IFHS
L7877:  LDB  #$1F
L7879:  LDX  APTR,U
L787B:  LDA  B,X                    ;GET CURRENT VOLUME ENV. ADJ.
L787D:  ADDA VVOL,U
L787F:  BPL  PKNC_5                 ;IF NUM NOT .LT. 0
L7881:  CLRA                        ;ELSE, SET VOLUME TO OFF

PKNC_5:
L7882:  CMPA #$10                   ;CHECK FOR VOLUME TOO LARGE
L7884:  BLT  PKNC_6                 ;IF VOLUME OK
L7886:  LDA  #$0F                   ;ELSE, SET TO MAX.

PKNC_6:
L7888:  ORA  VAC,U                  ;SET UP CURRENT VOICE CONTROL
L788A:  ANDA FASV                   ;MASK WITH NOTE ON/OFF SETTING
L788C:  LDX  VCS_PKF,Y              ;SELECT THE POKEY OUTPUT PORT
L788E:  LDB  DREF
L7890:  BEQ  PKNC_62                ;?DYNAMICALLY RECONFIG'D?
L7892:  LDX  VCS_PKD,Y              ;THEN USE DRE PORT INSTEAD
L7894:  STA  1,X                    ;ONLY DO LO 8 BITS
L7896:  RTS                         ;EXIT ALL DONE

PKNC_62:
PKNC_67:
L7897:  STA  3,X                    ;AMPLITUDE GOES IN SECOND CHANNEL FOR 16 BIT
L7899:  RTS                         ;EXIT ALL DONE

;------------------------------------------------------------------------------
; PKFUN - HAVE A FUNCTION, NOT A NOTE..
;   B:= OPCODE
;------------------------------------------------------------------------------
PKFUN:
L789A:  LDX  OPTR,U
L789C:  LDA  -$1,X                  ;A:= DATA VALUE
L789E:  LSLB
L789F:  CMPB #PKDTZ-PKDT
L78A1:  LBHS POKNL                  ;NULL OUT IF NOT IN RANGE
L78A5:  LDX  #PKDT                  ;DISPATCH BASE
L78A8:  JMP  [B,X]                  ;GOTO ROUTINE

PKDT:            ;DISPATCH TABLE
L78AA:  .word PKARAT, PKCRAT
L78AE:  .word PKAAMP, PKCAMP
L78B2:  .word PKAKEY, PKCKEY
L78B6:  .word PKFRQE
L78B8:  .word PKAMPE
L78BA:  .word POKNL, POKNL
L78BE:  .word PKCON, PKPKC
L78C2:  .word PKSYN
L78C4:  .word PKCPH
L78C6:  .word PKSL, PKEL
L78CA:  .word PKGOSB, PKRET

;------------------------------------------------------------------------------
; PKDTZ - HAVE AN AMPLITUDE ENV. FUNCTION
;   (also: PKAMPE)
;------------------------------------------------------------------------------
PKDTZ:
PKAMPE:
L78CE:  LSLA                        ;WORD POINTER
L78CF:  TFR  A,B                    ;PREPARE FOR UNSIGNED 256 LENGTH ADD
L78D1:  LDX  #AETAB                 ;BASE OF AMPLITUDE DIRECTORY
L78D4:  ABX
L78D5:  LDD  ,X                     ;GET AMP POINTER
L78D7:  STD  APTR,U
L78D9:  JMP  POKNL

;------------------------------------------------------------------------------
; PKFRQE - HAVE A FREQ. FUNCITON
;------------------------------------------------------------------------------
PKFRQE:
L78DC:  LSLA                        ;WORD POINTER
L78DD:  TFR  A,B                    ;PREPARE FOR 256 LENGTH UNSIGNED ADD
L78DF:  LDX  #FETAB                 ;BASE OF FREQUENCY TABLE
L78E2:  ABX
L78E3:  LDD  ,X                     ;GET FREQ POINTER
L78E5:  STD  FPTR,U
L78E7:  JMP  POKNL                  ;NEXT INSTRUCTION PLEASE

;------------------------------------------------------------------------------
; PKCRAT - HAVE A RATE FUNCTION
;------------------------------------------------------------------------------
PKCRAT:
L78EA:  SUBA ORATE,U                ;IF CHANGE RATE, ADD NEW(POSITIVE) TO OLD(NEGATIVE

;------------------------------------------------------------------------------
; PKARAT - [note] Tune function (PKDT entry 0), have a new rate: ORATE = -A (stored pre-negated), then POKNL.
;   PKCRAT (change rate) falls into this. A = data value, U-->voice RAM block
;------------------------------------------------------------------------------
PKARAT:
L78EC:  NEGA                        ;FORM NEGATIVE, 8 BIT VALUE, 9 BIT IMPLIED NEGATIVE
L78ED:  STA  ORATE,U                ;IF NEW RATE, STORE DESIRED VALUE
L78EF:  JMP  POKNL

;------------------------------------------------------------------------------
; PKCAMP - HAVE A NEW MEDIAN AMPLITUDE
;------------------------------------------------------------------------------
PKCAMP:
L78F2:  ADDA VVOL,U                 ;IF CHANGE AMPLITUDE, ADD NEW TO OLD

;------------------------------------------------------------------------------
; PKAAMP - [note] Tune function (PKDT entry 2), have a new median amplitude: VVOL = A, then POKNL.
;   PKCAMP (change amplitude) falls into this. A = data value, U-->voice RAM block
;------------------------------------------------------------------------------
PKAAMP:
L78F4:  STA  VVOL,U                 ;IF NEW AMPLITUDE, STORE DESIRED VALUE
L78F6:  JMP  POKNL

;------------------------------------------------------------------------------
; PKCKEY - HAVE A NEW KEY OFFSET
;------------------------------------------------------------------------------
PKCKEY:
L78F9:  ADDA OKEY,U                 ;IF CHANGE KEY, ADD NEW TO OLD

;------------------------------------------------------------------------------
; PKAKEY - [note] Tune function (PKDT entry 4), have a new key offset: OKEY = A, then POKNL.
;   PKCKEY (change key) falls into this. A = data value, U-->voice RAM block
;------------------------------------------------------------------------------
PKAKEY:
L78FB:  STA  OKEY,U                 ;IF NEW KEY, SET DESIRED VALUE
L78FD:  JMP  POKNL

;------------------------------------------------------------------------------
; PKCON - HAVE NEW VOICE CONTROL BITS
;------------------------------------------------------------------------------
PKCON:
L7900:  STA  VAC,U                  ;STORE INTO VOICE CONTROL BITS
L7902:  JMP  POKNL

;------------------------------------------------------------------------------
; PKPKC - WANT TO SET UP NEW POKEY CONTROL BITS (FOR POKEY 1)
;------------------------------------------------------------------------------
PKPKC:
L7905:  STA  PKC1                   ;STORE INTO POKEY 1
L7908:  JMP  POKNL

;------------------------------------------------------------------------------
; PKSYN - WANT TO SET OR RESET SYNTH MODE
;------------------------------------------------------------------------------
PKSYN:
L790B:  STA  VSF,U                  ;STORE INTO SYNTH. FLAG
L790D:  JMP  POKNL

;------------------------------------------------------------------------------
; PKCPH - WANT TO CALL A SUB-PHRASE
;------------------------------------------------------------------------------
PKCPH:
L7910:  LSLA                        ;WORD POINTER
L7911:  TFR  A,B                    ;PREPARE FOR 256 BYTE TABLE
L7913:  LDX  #TUNTAB                ;BASE OF DIRECTORY
L7916:  ABX
L7917:  LDD  OPTR,U
L7919:  STD  OPTSV,U                ;SAVE CURRENT PC
L791C:  LDD  ,X                     ;GET NEW SUBTUNE
L791E:  STD  OPTR,U
L7920:  JMP  POKNL

;------------------------------------------------------------------------------
; PKSL - WANT TO START A PHRASE LOOP
;------------------------------------------------------------------------------
PKSL:
L7923:  STA  VLC,U                  ;SAVE LOOP COUNT FOR THIS PHRASE
L7926:  LDD  OPTR,U                 ;GET CURRENT PC
L7928:  STD  OPTLL,U                ;AND SAVE IT
L792B:  JMP  POKNL

;------------------------------------------------------------------------------
; PKEL - WANT TO END A PHRASE LOOP
;------------------------------------------------------------------------------
PKEL:
L792E:  DEC  VLC,U                  ;CHECK FOR DONE WITH LOOP
L7931:  LBEQ POKNL                  ;B IF DONE WITH LOOP, CONTINUE FROM HERE
;ARE NOT DONE YET WITH LOOP, REINSTATE ADDRESSES OF LOOP START
L7935:  LDD  OPTLL,U
L7938:  STD  OPTR,U
L793A:  JMP  POKNL

;------------------------------------------------------------------------------
; PKGOSB - [note] Tune function, gosub to a subphrase: save the address past this 3 byte instruction in OPTRET, load
;   OPTR from the instruction's last two bytes, then POKNL. U-->voice RAM block
;------------------------------------------------------------------------------
PKGOSB:
L793D:  LDX  OPTR,U                 ;LOAD CURRENT PC
L793F:  LEAX 1,X                    ;BUMP PAST THE 3 BYTE INSTRUCTION
L7941:  STX  OPTRET,U               ;SAVE IT IN RETURN POINTER
L7944:  LDD  -$2,X                  ;GET CURRENT ADDRESS TO JUMP TO (SUBPHRASE)
L7946:  STD  OPTR,U                 ;PUT IN OLD POINTER
L7948:  JMP  POKNL

;------------------------------------------------------------------------------
; PKRET - [note] Tune function, return from gosub: OPTR = OPTRET, then POKNL. U-->voice RAM block
;------------------------------------------------------------------------------
PKRET:
L794B:  LDD  OPTRET,U
L794E:  STD  OPTR,U
L7950:  JMP  POKNL

